        #[cfg(not(test))]
        if let Some(file) = file() {
            return std::fs::read_to_string(file).is_ok_and(|text| text.trim() == "wrap");
        }
        false
    }

    /// Saves the choice; it is only a convenience, so failing to is ignored.
